#!/usr/bin/env bash
# Pixel-art Clawd living in his room on a waybar custom module.
# Frames, position classes and station coordinates come from clawd.css (see gen.py).
# Click (SIGUSR1) makes him hop.

DIR=$(dirname "$(readlink -f "$0")")
DELAY=${CLAWD_DELAY:-0.1}

# stations as generated by gen.py: home=104 bed=6 ...
declare -A AT
for kv in $(sed -n 's|.*clawd: \(.*\) \*/.*|\1|p' "$DIR/clawd.css"); do
    AT[${kv%%=*}]=${kv#*=}
done

pos=${AT[home]}
look=c
blink=0
hop=0

trap 'hop=4' USR1

while :; do
    if (( hop > 0 )); then
        frame=hop-$look
        (( hop-- ))
    elif (( blink > 0 )); then
        frame=blink-$look
        (( blink-- ))
    else
        frame=look-$look
        (( RANDOM % 40 == 0 )) && blink=2
        if (( RANDOM % 60 == 0 )); then
            dirs=(l c r c)
            look=${dirs[RANDOM % 4]}
        fi
    fi

    printf '{"text":" ","tooltip":"Clawd","class":["f-%s","p-%d"]}\n' "$frame" "$pos"

    sleep "$DELAY" & wait $!
done
